const API_URL = String(import.meta.env.VITE_API_URL || '').trim().replace(/\/$/, '');
const CONFIGURED_API_KEY = String(import.meta.env.VITE_API_KEY || '').trim();
let runtimeApiKey = '';
let runtimeCsrf = '';
const OPERATOR_CONTROLS = import.meta.env.VITE_ENABLE_OPERATOR_CONTROLS === 'true';
const POLL_MS = 30_000;

type Tab = 'overview' | 'decisions' | 'orders' | 'metrics' | 'scars' | 'operations' | 'architecture' | 'eda' | 'settings';
type RuntimeConfig = { values: Record<string, unknown>; schema: Record<string, { label: string; description: string; type: string; default: unknown; min?: number; max?: number; options?: string[]; group: string }>; history: Array<{ version: number; changes: Record<string, unknown>; previous: Record<string, unknown>; updated_by: string; reason: string; updated_at: string }> };
type Decision = { id: string; action: string; side: string | null; size: number; edge: number; confidence: number; risk_score: number; rationale: string; cited_scars: string[]; gates: string[]; order_id?: string; expected_value: number; executable_price?: number; paper_execution_price?: number | null; paper_fill_fraction?: number; model_version?: string | null; research_eligible?: boolean; raw_model_probability?: number | null; model_probability?: number | null; model_lower_bound?: number | null; model_upper_bound?: number | null; model_uncertainty?: number | null; model_calibration_samples?: number; model_calibration_status?: string; model_provenance?: { components?: Array<{ strategy_id?: string; probability?: number; weight?: number }>; weighting?: { method?: string } }; market_context?: { resolution_hours?: number; fee_rate?: number; slippage_bps?: number; quote_skew_seconds?: number } };
type Scar = { id: string; severity: number; lesson: string; principle: string; type?: string; failure_type?: string; process_score?: number; rehabilitation_progress?: number; rehabilitation_required?: number; rehabilitation_condition?: string; cooldown_until?: string | null; resolved_at?: string | null; status?: string; impact: { cooldown_hours: number; max_size_multiplier?: number } };
type Order = { id: string; decision_id: string; side: string; requested_size: number; status: string; filled_size: number; average_fill_price: number | null; error: string | null };
type Dashboard = { mode?: string; risk?: { portfolio_heat?: number; max_portfolio_heat?: number; realized_pnl?: number; daily_pnl?: number; weekly_pnl?: number; correlation_regime?: string }; pipeline?: { stage?: string; snapshots?: number; data_ready?: boolean; next_stage?: string }; observations?: { distinct_markets?: number } };
type Observability = { ingestion?: { score?: number; stale?: boolean; snapshots?: number; raw_snapshots?: number; observed_snapshots?: number; invalid_observations?: number; invalid_books?: number; book_coverage?: number; last_observed_at?: string | null; last_snapshot_at?: string | null; quality?: { score?: number; stale?: boolean } }; worker?: { status?: string; last_tick_at?: string | null; last_success_at?: string | null; last_error?: string | null; last_markets?: number; last_books?: number; last_resolution_at?: string | null; last_resolved?: number; last_resolution_errors?: number; last_pending?: number; error_count?: number }; telemetry?: { recent_errors_5m?: number } };
type Metric = { strategy_id?: string; market_type?: string; expectancy?: number; decisions?: number; wins?: number; pnl?: number; decision_quality?: number; rule_adherence?: number; regime?: string; model_version?: string | null; brier_score?: number | null; log_loss?: number | null; calibration_error?: number | null; profit_factor?: number };
type Alert = { code: string; severity: string; message: string };
