type MarketInput = { market_id: string; question: string; market_type?: string; price: number; volume_24h?: number; liquidity?: number; reference_rate?: number | null; signals?: Record<string, number>; source?: string; observed_at?: string | null; quote_observed_at?: string | null; quality_score?: number; snapshot_hash?: string | null; book_sequence?: number | null; yes_bid?: number | null; yes_ask?: number | null; no_bid?: number | null; no_ask?: number | null; book_bids?: unknown[]; book_asks?: unknown[] };
type ReadinessSummary = { summary?: string; learning_status?: string; automation?: { enabled?: boolean; decisions_per_tick?: number; exploration_enabled?: boolean; exploration_max_per_tick?: number; exploration_size?: number; cooldown_seconds?: number; min_resolution_hours?: number; max_resolution_hours?: number; fast_markets_only?: boolean; fast_max_resolution_hours?: number; prefer_fast_markets?: boolean }; paper?: { decisions?: number; exposed?: number; exploration_exposed?: number; research_exposed?: number; independent_buckets?: number; resolved?: number; independent_resolved?: number; pending?: number; independent_pending?: number; wins?: number; win_rate?: number | null; pnl?: number; metrics_buckets?: number; minimum_sample?: number }; data?: { snapshots?: number; minimum_snapshots?: number; quality?: number; book_coverage?: number; stale?: boolean }; worker?: { status?: string; last_resolved?: number; last_pending?: number }; live?: { eligible?: boolean; blockers?: string[] } };
type EdaHealth = { integrity?: { healthy?: boolean; episodes?: number; events?: number; orphan_events?: number; invalid_episode_hashes?: string[] }; opportunities?: number; replay_runs?: number; models?: number; telemetry?: { counters?: Record<string, number>; gauges?: Record<string, number>; recent_errors_5m?: number } };
type Opportunity = { opportunity_id: string; market_id: string; strategy_id: string; status: string; reason?: string | null; observed_at?: string };
type ReplayRun = { replay_id: string; episode_id: string; mode: string; as_of: string; result?: { mismatch?: boolean; lookahead_excluded?: number; versions?: { replayed_objective_policy?: string } } };
type RegistryModel = { model_id: string; version: string; status: string; metrics?: Record<string, unknown>; approved_by?: string | null; rollback_target?: string | null };
type Snapshot = { decisions: Decision[]; scars: Scar[]; orders: Order[]; hot: HotMarket[]; dashboard: Dashboard; obs: Observability; metrics: Metric[]; alerts: Alert[]; summary: ReadinessSummary; eda: { health: EdaHealth; opportunities: Opportunity[]; replays: ReplayRun[]; models: RegistryModel[] } };
const emptySnapshot: Snapshot = { decisions: [], scars: [], orders: [], hot: [], dashboard: {}, obs: {}, metrics: [], alerts: [], summary: {}, eda: { health: {}, opportunities: [], replays: [], models: [] } };
function marketId(market: HotMarket) { return String(market.market_id || (market as HotMarket & { id?: string }).id || (market as HotMarket & { conditionId?: string }).conditionId || ''); }
function ingestionQuality(obs: Observability) { return Number(obs.ingestion?.score ?? obs.ingestion?.quality?.score ?? 0); }
function ingestionStale(obs: Observability) { return Boolean(obs.ingestion?.stale ?? obs.ingestion?.quality?.stale ?? true); }

function readableDetail(value: unknown): string {
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(readableDetail).filter(Boolean).join('; ');
  if (value && typeof value === 'object') {
    const item = value as Record<string, unknown>;
    if (item.msg) return `${Array.isArray(item.loc) ? `${item.loc.join('.')} — ` : ''}${readableDetail(item.msg)}`;
    if (item.message) return readableDetail(item.message);
    try { return JSON.stringify(value); } catch { return 'Structured error response'; }
  }
  return value == null ? '' : String(value);
}

async function api<T>(path: string, options: RequestInit = {}, signal?: AbortSignal): Promise<T> {
  if (!API_URL) throw new Error('Frontend is not configured: set VITE_API_URL in the deployment environment.');
  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), 30_000);
  const relayAbort = () => controller.abort();
  signal?.addEventListener('abort', relayAbort, { once: true });
  try {
    const method = String(options.method || 'GET').toUpperCase();
    const requestHeaders = new Headers(options.headers);
    requestHeaders.set('Accept', 'application/json');
    const csrfCookie = document.cookie.split('; ').find(item => item.startsWith('vesper_csrf='))?.split('=').slice(1).join('=');
    const csrf = runtimeCsrf || csrfCookie || '';
    // Keep the API-key fallback available even when a session CSRF token is
    // present. Cross-origin cookies can be unavailable in some browsers, and
    // the key is the authenticated fallback for read requests.
    if ((runtimeApiKey || CONFIGURED_API_KEY) && !requestHeaders.has('X-Vesper-Key')) requestHeaders.set('X-Vesper-Key', runtimeApiKey || CONFIGURED_API_KEY);
    if (method === 'GET' || method === 'HEAD') requestHeaders.delete('Content-Type');
    else requestHeaders.set('Content-Type', 'application/json');
    if (method !== 'GET' && method !== 'HEAD') requestHeaders.set('X-Vesper-CSRF', decodeURIComponent(csrf || ''));
    const response = await fetch(`${API_URL}${path}`, { ...options, credentials: 'include', signal: controller.signal, headers: requestHeaders });
    const text = await response.text();
    let body: unknown = null;
    try { body = text ? JSON.parse(text) : null; } catch { body = null; }
    if (!response.ok) {
      const record = body && typeof body === 'object' ? body as Record<string, unknown> : {};
      const detail = readableDetail(record.detail ?? record.message ?? body);
      const requestId = response.headers.get('x-request-id');
      throw new Error(`${detail || `Request failed (${response.status})`}${requestId ? ` · Request ${requestId}` : ''}`);
    }
    return body as T;
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') throw new Error('Request timed out. Check the API and try again.');
    if (error instanceof TypeError && /fetch/i.test(error.message)) throw new Error(`Unable to reach the Vesper API at ${API_URL}. Check VITE_API_URL and backend CORS_ORIGINS.`);
    throw error;
  } finally { window.clearTimeout(timeout); signal?.removeEventListener('abort', relayAbort); }
}
function formatTime(value?: string | null) { if (!value) return 'never'; const date = new Date(value); return Number.isNaN(date.valueOf()) ? 'unknown' : date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }); }
function percent(value: unknown, digits = 1) { return `${(Number(value || 0) * 100).toFixed(digits)}%`; }
function number(value: unknown, digits = 2) { return Number(value || 0).toFixed(digits); }
const navItems: { id: Tab; label: string; icon: typeof LayoutDashboard }[] = [
  { id: 'overview', label: 'Overview', icon: LayoutDashboard }, { id: 'decisions', label: 'Decisions', icon: ClipboardList }, { id: 'orders', label: 'Orders', icon: Zap }, { id: 'metrics', label: 'Performance', icon: BarChart3 }, { id: 'scars', label: 'System memory', icon: BookOpen }, { id: 'operations', label: 'System health', icon: Database }, { id: 'architecture', label: 'System guide', icon: CircleHelp }, { id: 'settings', label: 'Settings', icon: SettingsIcon },
];
const pageMeta: Record<Tab, { title: string; subtitle: string }> = {
  overview: { title: 'System overview', subtitle: 'See what the automatic worker is doing and what needs attention.' },
  decisions: { title: 'Decision history', subtitle: 'Every paper test, position, result, and reason.' },
  orders: { title: 'Paper trades', subtitle: 'Simulated fills, costs, and results.' },
  metrics: { title: 'Performance', subtitle: 'Results after fees, simulated fills, and losses.' },
  scars: { title: 'System memory', subtitle: 'Lessons from losses and rules that now limit the system.' },
  operations: { title: 'System health', subtitle: 'Worker status, data collection, alerts, and why real trading is off.' },
  architecture: { title: 'System guide', subtitle: 'A map of every major component, data boundary, and safety gate.' },
  settings: { title: 'Settings', subtitle: 'Safe controls for paper testing and execution assumptions.' },
  eda: { title: 'Audit trail', subtitle: 'A record of what the system saw and why it acted.' },
};
function readTab(): Tab { const value = window.location.hash.replace('#/', '') as Tab; return navItems.some(item => item.id === value) ? value : 'overview'; }

function SessionGate({ children }: { children: React.ReactNode }) {
  const [state, setState] = useState<'checking' | 'login' | 'ready'>('checking');
  useEffect(() => { if (sessionStorage.getItem('vesper_force_login') === 'true') { setState('login'); return; } api<{ csrf?: string }>('/auth/session').then(session => { runtimeCsrf = session.csrf || ''; setState('ready'); }).catch(() => setState('login')); }, []);
  if (state === 'checking') return <div className="auth-screen"><div className="auth-card"><div className="brand-mark">V</div><h1>Connecting to Vesper</h1><p>Verifying your secure session…</p></div></div>;
  if (state === 'login') return <LoginScreen onAuthenticated={() => setState('ready')} />;
  return <>{children}</>;
}

function LoginScreen({ onAuthenticated }: { onAuthenticated: () => void }) {
  const [key, setKey] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const submit = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { if (!API_URL) throw new Error('Set VITE_API_URL before signing in.'); const response = await fetch(`${API_URL}/auth/session`, { method: 'POST', credentials: 'include', headers: { 'X-Vesper-Key': key.trim(), Accept: 'application/json' } }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(String(body.detail || `Sign-in failed (${response.status})`)); runtimeApiKey=key.trim(); runtimeCsrf=String(body.csrf || ''); sessionStorage.removeItem('vesper_force_login'); setKey(''); onAuthenticated(); } catch (e) { setError(e instanceof TypeError && /fetch/i.test(e.message) ? `Unable to reach the Vesper API at ${API_URL}. Check VITE_API_URL and backend CORS_ORIGINS.` : e instanceof Error ? e.message : 'Sign-in failed.'); } finally { setBusy(false); } };
  return <div className="auth-screen"><form className="auth-card" onSubmit={submit}><div className="brand-mark">V</div><div className="eyebrow">VESPER TRADING / SECURE SESSION</div><h1>Enter your access key</h1><p>Your key is exchanged once for an HttpOnly backend session. It is never stored in the frontend bundle.</p><label className="field"><span>Vesper access key</span><input type="password" autoComplete="current-password" value={key} onChange={e => setKey(e.target.value)} required placeholder="Paste access key" /></label>{error && <div className="auth-error" role="alert"><AlertTriangle size={16} />{error}</div>}<button className="primary-button auth-submit" disabled={busy || !key.trim()}>{busy ? 'Signing in…' : 'Create secure session'}</button><small className="auth-foot">Sessions expire automatically. Admin scope is enforced by the backend.</small></form></div>;
}

function App() {
  const [tab, setTab] = useState<Tab>(readTab); const [snapshot, setSnapshot] = useState<Snapshot>(emptySnapshot); const [loading, setLoading] = useState(true); const [refreshing, setRefreshing] = useState(false); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [mobileOpen, setMobileOpen] = useState(false); const [price, setPrice] = useState(0.6); const [flow, setFlow] = useState(0); const [marketQuery, setMarketQuery] = useState(''); const [runtimeConfig, setRuntimeConfig] = useState<RuntimeConfig | null>(null); const requestRef = useRef<AbortController | null>(null);
  const navigate = useCallback((next: Tab) => { setTab(next); window.history.replaceState(null, '', `#/${next}`); setMobileOpen(false); window.scrollTo({ top: 0, left: 0, behavior: 'instant' }); }, []);
  useEffect(() => { const onHash = () => { setTab(readTab()); window.scrollTo({ top: 0, left: 0, behavior: 'instant' }); }; window.addEventListener('hashchange', onHash); return () => window.removeEventListener('hashchange', onHash); }, []);
  const load = useCallback(async (background = false) => {
    requestRef.current?.abort(); const controller = new AbortController(); requestRef.current = controller; background ? setRefreshing(true) : setLoading(true);
    const sources = [
      ['decisions', api<Decision[]>('/decisions', {}, controller.signal)], ['system memory', api<Scar[]>('/scars', {}, controller.signal)], ['paper trades', api<Order[]>('/orders', {}, controller.signal)], ['market list', api<HotMarket[]>('/markets?limit=20&fast_only=true', {}, controller.signal)], ['system overview', api<Dashboard>('/dashboard', {}, controller.signal)], ['worker health', api<Observability>('/observability', {}, controller.signal)], ['performance metrics', api<Metric[]>('/metrics', {}, controller.signal)], ['alerts', api<{ active?: Alert[] }>('/alerts', {}, controller.signal)], ['trading readiness', api<ReadinessSummary>('/readiness/summary', {}, controller.signal)], ['audit health', api<EdaHealth>('/eda/health', {}, controller.signal)], ['market opportunities', api<Opportunity[]>('/eda/opportunities?limit=20', {}, controller.signal)], ['past test runs', api<ReplayRun[]>('/eda/replays?limit=20', {}, controller.signal)], ['prediction models', api<RegistryModel[]>('/eda/models', {}, controller.signal)],
    ] as const;
    const result = await Promise.allSettled(sources.map(([, request]) => request));
    if (controller.signal.aborted) return;
    const values = result.map(item => item.status === 'fulfilled' ? item.value : undefined); const failed = result.map((item, index) => item.status === 'rejected' ? sources[index][0] : '').filter(Boolean);
    const asArray = <T,>(value: unknown): T[] => Array.isArray(value) ? value as T[] : [];
    setSnapshot({ decisions: asArray<Decision>(values[0]), scars: asArray<Scar>(values[1]), orders: asArray<Order>(values[2]), hot: asArray<HotMarket>(values[3]), dashboard: (values[4] as Dashboard) || {}, obs: (values[5] as Observability) || {}, metrics: asArray<Metric>(values[6]), alerts: Array.isArray((values[7] as { active?: Alert[] })?.active) ? (values[7] as { active: Alert[] }).active : [], summary: (values[8] as ReadinessSummary) || {}, eda: { health: (values[9] as EdaHealth) || {}, opportunities: asArray<Opportunity>(values[10]), replays: asArray<ReplayRun>(values[11]), models: asArray<RegistryModel>(values[12]) } });
    setError(failed.length ? String(failed.length) + ' data source' + (failed.length === 1 ? '' : 's') + ' unavailable: ' + failed.join(', ') + '.' : ''); setLoading(false); setRefreshing(false);
  }, []);
  useEffect(() => { void load(); const timer = window.setInterval(() => { if (document.visibilityState === 'visible') void load(true); }, POLL_MS); return () => { window.clearInterval(timer); requestRef.current?.abort(); }; }, [load]);
  const loadRuntimeConfig = useCallback(async () => { try { setRuntimeConfig(await api<RuntimeConfig>('/operator/config')); } catch (e) { const message=e instanceof Error ? e.message : 'Unable to load runtime settings.'; if (message.includes('Insufficient session scope') || message.includes('Insufficient API scope')) { setRuntimeConfig(null); return; } setError(message); } }, []);
  useEffect(() => { if (tab === 'settings') void loadRuntimeConfig(); }, [tab, loadRuntimeConfig]);
  const post = async (path: string, body: unknown) => { setNotice(''); setError(''); try { await api(path, { method: 'POST', body: JSON.stringify(body) }); setNotice('Action accepted. Refreshing system state.'); await load(true); } catch (e) { setError(e instanceof Error ? e.message : 'Action failed.'); } };
  const logout = async () => { try { await api('/auth/session', { method: 'DELETE' }); } finally { runtimeApiKey=''; runtimeCsrf=''; sessionStorage.setItem('vesper_force_login', 'true'); window.location.reload(); } };
  const selectedMarket = useMemo(() => snapshot.hot.filter(m => !marketQuery || `${m.question || ''} ${marketId(m)}`.toLowerCase().includes(marketQuery.toLowerCase()))[0], [snapshot.hot, marketQuery]);
  const decide = async () => { const id = selectedMarket ? marketId(selectedMarket) : ''; try { const live = id ? await api<MarketInput>(`/markets/input/${encodeURIComponent(id)}`) : null; const market = live || { market_id: 'manual-paper-market', question: 'Manual paper decision', market_type: 'custom', liquidity: 0, volume_24h: 0, price: Number(price), reference_rate: Number(price), signals: {}, source: 'manual' }; await post('/decide', { market, strategy_id: 'reference_class', flow_imbalance: Number(flow), execute: true }); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to load the live market input.'); } };
  const { dashboard, obs } = snapshot; const mode = dashboard.mode || 'paper'; const quality = ingestionQuality(obs); const workerHealthy = obs.worker?.status === 'healthy'; const meta = pageMeta[tab];
  return <div className="app-shell"><a className="skip-link" href="#main-content">Skip to content</a><div className={`mobile-scrim ${mobileOpen ? 'visible' : ''}`} onClick={() => setMobileOpen(false)} aria-hidden="true" />
    <aside className={`sidebar ${mobileOpen ? 'open' : ''}`} aria-label="Primary navigation"><div className="brand"><div className="brand-mark">V</div><div><strong>VESPER</strong><span>TRADING / PAPER FIRST</span></div><button className="icon-button mobile-close" onClick={() => setMobileOpen(false)} aria-label="Close navigation"><X size={18} /></button></div><nav>{navItems.map(({ id, label, icon: Icon }) => <button key={id} type="button" className={tab === id ? 'active' : ''} aria-current={tab === id ? 'page' : undefined} onClick={() => navigate(id)}><Icon size={17} aria-hidden="true" /><span>{label}</span></button>)}</nav><div className="sidebar-foot"><span className={`status-dot ${workerHealthy ? 'good' : 'warn'}`} /> <span>{workerHealthy ? 'Systems nominal' : 'Needs attention'}</span><small>Mode: {mode}</small></div></aside>
    <main id="main-content" className={`main-content page-${tab}`}><header className="topbar"><div className="title-wrap"><button className="icon-button mobile-menu" onClick={() => setMobileOpen(true)} aria-label="Open navigation" aria-expanded={mobileOpen}><Menu size={20} /></button><div><div className="eyebrow">VESPER TRADING / CONTROL ROOM</div><h1 key={tab}>{meta.title}</h1><p key={`${tab}-subtitle`}>{meta.subtitle}</p></div></div><div className="topbar-actions"><div className={`mode-pill ${mode === 'live' ? 'danger' : ''}`}><span>MODE</span><strong>{mode}</strong></div><button className="secondary-button" type="button" onClick={() => void load(true)} disabled={loading || refreshing}><RefreshCw size={15} className={refreshing ? 'spin' : ''} />{refreshing ? 'Refreshing' : 'Refresh'}</button><button className="secondary-button" type="button" onClick={() => void logout()}><LogOut size={15} />Sign out</button></div></header>
      {(!API_URL) && <div className="banner danger-banner" role="alert"><AlertTriangle size={18} /><div><strong>Deployment configuration required</strong><span>VITE_API_URL is missing. The interface is fail-closed until configured.</span></div></div>}{error && <div className="banner error-banner" role="alert"><AlertTriangle size={18} /><div><strong>Some systems need attention</strong><span>{error}</span></div><button className="banner-action" onClick={() => void load()} type="button">Retry</button></div>}{notice && <div className="banner success-banner" role="status"><CheckCircle2 size={18} /><span>{notice}</span><button className="banner-dismiss" onClick={() => setNotice('')} aria-label="Dismiss notification"><X size={16} /></button></div>}
      <section className="hero-grid" aria-label="System summary"><div className="metric-card accent"><span>{mode === 'paper' ? 'PAPER P&L' : 'LIVE P&L'}</span><strong>{number(dashboard.risk?.realized_pnl)}</strong><small>Today {number(dashboard.risk?.daily_pnl)} · week {number(dashboard.risk?.weekly_pnl)}</small></div><div className="metric-card"><span>DATA QUALITY</span><strong>{percent(quality)}</strong><small>{obs.worker?.status || 'Worker unknown'} · {ingestionStale(obs) ? 'stale' : 'fresh'}</small><div className="metric-bar"><i style={{ width: `${Math.min(100, Number(quality) * 100)}%` }} /></div></div><div className="metric-card"><span>ERRORS IN 5 MIN</span><strong>{obs.telemetry?.recent_errors_5m || 0}</strong><small>{snapshot.alerts.length} active alerts</small></div><div className="metric-card"><span>MARKETS WITH DATA</span><strong>{dashboard.observations?.distinct_markets || 0}</strong><small>{obs.ingestion?.raw_snapshots || 0} raw snapshots · {obs.ingestion?.snapshots || 0} sampled observations</small></div></section>
      {tab === 'overview' && <><ReadinessSummaryCard summary={snapshot.summary} decisions={snapshot.decisions} /><EvidenceProfile summary={snapshot.summary} /><Overview snapshot={snapshot} marketQuery={marketQuery} setMarketQuery={setMarketQuery} price={price} setPrice={setPrice} flow={flow} setFlow={setFlow} decide={decide} post={post} loading={loading} operatorControls={OPERATOR_CONTROLS} /></>}{tab === 'decisions' && <Collection title="Recent decisions" eyebrow="COLD / JOURNAL" icon={<Sparkles size={16} />} query={marketQuery} setQuery={setMarketQuery}>{snapshot.decisions.length ? snapshot.decisions.slice(0, 50).map(item => <DecisionCard key={item.id} item={item} />) : <Empty title="No decisions recorded" text="When the decision engine records its first event, it will appear here." />}</Collection>}{tab === 'orders' && <Collection title="Order lifecycle" eyebrow="EXECUTION / AUDIT" icon={<Zap size={16} />} query={marketQuery} setQuery={setMarketQuery}>{snapshot.orders.length ? snapshot.orders.slice(0, 50).map(item => <OrderCard key={item.id} item={item} />) : <Empty title="No orders yet" text="Paper orders will appear here after a decision is evaluated." />}</Collection>}{tab === 'metrics' && <Collection title="Process performance" eyebrow="PROCESS / PERFORMANCE" icon={<BarChart3 size={16} />} query={marketQuery} setQuery={setMarketQuery}>{snapshot.metrics.length ? snapshot.metrics.map((item, index) => <MetricCard key={`${item.strategy_id}-${item.market_type}-${item.regime}-${item.model_version || 'none'}-${index}`} item={item} />) : <Empty title="No settled process buckets" text="Metrics will populate as outcomes settle." />}</Collection>}{tab === 'scars' && <Collection title="Scars and operating rules" eyebrow="WARM / EXPERIENCE" icon={<BookOpen size={16} />} query={marketQuery} setQuery={setMarketQuery}>{snapshot.scars.length ? snapshot.scars.map(item => <ScarCard key={item.id} item={item} />) : <Empty title="No scars recorded" text="Durable lessons will appear here as the system learns." />}</Collection>}{tab === 'operations' && <Operations snapshot={snapshot} />}{tab === 'architecture' && <ArchitectureGuide />}{tab === 'settings' && <RuntimeSettings config={runtimeConfig} onSaved={loadRuntimeConfig} setError={setError} setNotice={setNotice} />}<footer className="footer"><span><ShieldCheck size={14} /> Authenticated control surface</span><span>Last worker success: {formatTime(obs.worker?.last_success_at)}</span></footer></main></div>;
}

type GuideCardData = { file: string; title: string; text: string };

